import{_ as n,l as o,o as e,c as l,v as i,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Z 函数","description":"","frontmatter":{"title":"Z 函数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/z-function.md","filePath":"cs/z-function.md","lastUpdated":1789023840000}'),c={name:"cs/z-function.md"};function u(_,a,m,P,f,Z){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="z-函数" tabindex="-1">Z 函数 <a class="header-anchor" href="#z-函数" aria-label="Permalink to &quot;Z 函数&quot;">​</a></h1><div class="epigraph"><p>$Z[i]$ 是 $s[i..]$ 与 $s$ 的最长公共前缀；维护已匹配窗口 $[l,r]$，线性扫完，与 KMP 前缀函数互推。</p><footer>—— 据 Gusfield, Algorithms on Strings, Trees and Sequences；CLRS 第 32 章对照整理</footer></div><p>上一课<a href="/cs/knuth-opt-matrix-chain">矩阵链与 Knuth 优化</a>收束 DP 进阶。本单元进入字符串。主干<a href="/cs/kmp">KMP</a> 给了 \\(\\pi\\)。缺口是 Z 函数：每个后缀与全串的 LCP。匹配、本质不同子串、字符串周期都用 \\(Z\\)。不重写 \\(\\pi\\) 的自匹配证明。后课 Manacher 回文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(Z[0]\\) 约定 \\(0\\) 或 \\(n\\)。朴素每位 \\(O(n)\\) 比较最坏平方。Z-box：已匹配到 \\(r\\) 的窗口。若 \\(i\\le r\\)，可把 \\(Z[i-l]\\) 与 \\(r-i+1\\) 取 min 再尝试延长。均摊 \\(O(n)\\)：\\(r\\) 只增。</p><p>模式匹配：算 \\(P\\#T\\) 的 \\(Z\\)，凡 \\(Z[i]=|P|\\) 即出现。与 KMP 等价线性。</p><p>缺口是窗口，不是后缀数组（后课应用）。</p><h3 id="与-互推" tabindex="-1">\\(Z\\) 与 \\(\\pi\\) 互推 <a class="header-anchor" href="#与-互推" aria-label="Permalink to &quot;$Z$ 与 $\\pi$ 互推&quot;">​</a></h3><p>\\(\\pi\\) 与 \\(Z\\) 可 \\(O(n)\\) 互化。周期：若 \\(i+Z[i]=n\\) 等条件给出周期。不要两套都从平方枚举起。</p><p><span class="marginnote">Gusfield 系统写 Z。KMP 1977 是 \\(\\pi\\)。后课 Manacher 另用回文半径窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化 \\(l=r=0\\)。\\(i\\) 从 1 到 \\(n-1\\) 按盒内外更新。匹配用拼接串注意分隔符不在字母表。</p>',12)),(e(),s(h,null,{default:t(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%B2%20s%22%5D%20--%3E%20ZBOX%5B%22%E7%AA%97%E5%8F%A3%20%5Bl%2Cr%5D%22%5D%0A%20%20ZBOX%20--%3E%20Z%5B%22Z%5Bi%5D%20LCP%22%5D%0A%20%20Z%20--%3E%20M%5B%22P%23T%20%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>输出 \\(Z\\) 数组。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(r\\) 单调保证比较次数 \\(O(n)\\)。与 KMP：都是已匹配前缀的再利用。与后缀数组：LCP 是任意后缀对，本课只对对全串。与滚动哈希：Z 最坏线性确定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写后缀自动机。不写回文（下一课）。后课默认：与自身 LCP 用 Z；\\(O(n)\\)。下一课 Manacher。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(Z[i]\\)：后缀与全串 LCP。</li><li>Z-box 线性；可匹配、求周期。</li><li>与 \\(\\pi\\) 互推。</li><li>出处：Gusfield；KMP 见 Knuth, Morris and Pratt, 1977。</li></ul>',7))])}const x=n(c,[["render",u]]);export{b as __pageData,x as default};
